import ULThemeCard from "@/components/ULThemeCard";
import CoppelPageLayout from "@/components/CoppelPageLayout";
import { applyAuth0Theme } from "@/utils/theme";

import { useEffect } from "react";
import Header from "./components/Header";
import MFAEnrollOptions from "./components/MFAEnrollOptions";
import { useMfaBeginEnrollOptionsManager } from "./hooks/useMFABeginEnrollOptionsManager";
import { pushPageView } from "@/utils/helpers/dataLayerUtils";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";

function MFABeginEnrollOptions() {
  // Extracting attributes from hook made out of MFABeginEnrollOptionsInstance class of Auth0 React SDK
  const { mfaBeginEnrollOptions, locales } =
    useMfaBeginEnrollOptionsManager();

  // Apply theme from SDK instance when screen loads
  applyAuth0Theme(mfaBeginEnrollOptions);

  useEffect(() => {
    pushPageView("/protege-tu-cuenta", "Proteje tu cuenta", getCanalByClientId());
  }, []);

  return (
    // Applying UDS theme overrides using the "theme-universal" class
    <CoppelPageLayout className="theme-universal" pageTitle={locales?.page?.title} mainAriaLabel={locales?.header?.description}>
      <ULThemeCard className="w-full max-w-[400px] gap-0">
        <Header />
        <MFAEnrollOptions />
      </ULThemeCard>
    </CoppelPageLayout>
  );
}

export default MFABeginEnrollOptions;
